package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class DrawableContainer extends Drawable implements Drawable.Callback { protected Drawable[] children=new Drawable[0]; protected int current=-1; public boolean selectDrawable(int i){if(i<0||i>=children.length)return false;current=i;children[i].setBounds(getBounds());invalidateSelf();return true;} public Drawable getCurrent(){return current<0?this:children[current];} public void draw(Canvas c){if(current>=0)children[current].draw(c);} protected void onBoundsChange(Rect r){for(Drawable d:children)if(d!=null)d.setBounds(r);} public void invalidateDrawable(Drawable d){invalidateSelf();} public void scheduleDrawable(Drawable d,Runnable r,long t){scheduleSelf(r,t);} public void unscheduleDrawable(Drawable d,Runnable r){unscheduleSelf(r);} protected void add(Drawable d){Drawable[] n=new Drawable[children.length+1];for(int i=0;i<children.length;i++)n[i]=children[i];n[children.length]=d;children=n;d.setCallback(this);if(current<0)selectDrawable(0);} }